import { useLanguage } from '@/lib/LanguageProvider';
import PageHeader from '@/components/PageHeader';
import FilesView from '@/components/files/FilesView';
import { Sparkles } from 'lucide-react';

/**
 * MyFilesPage — standalone page for all agent-generated files and artifacts.
 * Extracted from the MySpace "file" tab and promoted to a top-level sidebar
 * navigation item for faster access with fewer clicks.
 */
export default function MyFilesPage() {
  const { t, lang } = useLanguage();
  const isEn = lang === 'en';

  return (
    <div className="h-full overflow-y-auto px-8 py-8">
      <PageHeader
        title={t.sidebar.myFiles || (isEn ? 'My Files' : '我的文件')}
        subtitle={isEn
          ? 'Every resource and asset your agents have built or generated — reports, dashboards, automation outputs and more.'
          : '你的智能体创建或生成的全部资源与资产——报表、仪表盘、自动化产物等。'}
      />
      <div className="mt-2 mb-6 inline-flex items-center gap-1.5 rounded-full bg-secondary px-2.5 py-1 text-xs text-muted-foreground">
        <Sparkles className="h-3 w-3" />
        <span>{isEn ? 'Generated by agents' : '由智能体生成'}</span>
      </div>
      <FilesView />
    </div>
  );
}
